public static TFMRegistrationCollectorTypeAndQuantity TypeAndQuantity(
                                    int _id,
                                    str _name,
                                    str _header,
                                    str _label,
                                    str _helpLabel,
                                    TFMScanBehaviour _scanBehaviour = TFMScanBehaviour::Add,
                                    boolean  _optional=false,
                                    str _eanAI = '')
{
    TFMRegistrationCollectorTypeAndQuantity collector = new TFMRegistrationCollectorTypeAndQuantity(_id,_name,_header,_label,_helpLabel);
    collector.parmEanAI(_eanAI);
    collector.parmScanBehavior(_scanBehaviour);
    collector.parmOptional(_optional);
    return collector;
}

public static Map TypeAndQuantityMap(
                                    int _id,
                                    str _name,
                                    str _header,
                                    str _label,
                                    str _helpLabel,
                                    TFMScanBehaviour _scanBehaviour = TFMScanBehaviour::Add,
                                    boolean  _optional=false,
                                    str _eanAI = '')
{
    return TFMRegistrationCollectorTypeAndQuantity::TypeAndQuantity(_id,_name,_header,_label,_helpLabel,_scanBehaviour,_optional,_eanAI).getMap();

}
